import sys
​
# 判断是否为素数
def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    # 只需要检查 6k ± 1 形式的数
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
​
# 判断是否为回文数
def is_symmetry_num(num: int) -> bool:
    return str(num) == str(num)[::-1]
​
def main():
    n = int(sys.stdin.readline().strip())

    while True:
        if is_symmetry_num(n) and is_prime(n):
            print(n)
            break
        n += 1  # 尝试下一个数
​
if __name__ == "__main__":
    main()
