    "os"
    "strconv"
)
​
// 判断是否为素数
func isPrime(n int) bool {
    if n < 2 {
        return false
    }
    if n == 2 || n == 3 {
        return true
    }
    if n%2 == 0 || n%3 == 0 {
        return false
    }
    // 只需要检查 6k ± 1 形式的数
    for i := 5; i*i <= n; i += 6 {
        if n%i == 0 || n%(i+2) == 0 {
            return false
        }
    }
    return true
}
​
// 判断是否为回文数
func isSymmetryNum(num int) bool {
    s := strconv.Itoa(num)
    i, j := 0, len(s)-1
    for i < j {
        if s[i] != s[j] {
            return false
        }
        i++
        j--
    }
    return true
}
